import org.springframework.http.client.BufferingClientHttpRequestFactory
import org.springframework.http.client.ClientHttpRequestFactory

class Bad(delegate: ClientHttpRequestFactory) {
    val factory = BufferingClientHttpRequestFactory(delegate) // bad
}

import org.springframework.http.client.BufferingClientHttpRequestFactory
import org.springframework.http.client.ClientHttpRequestFactory

fun wrapAll(delegates: List<ClientHttpRequestFactory>) =
    delegates.map {
        BufferingClientHttpRequestFactory(it) // bad - created per element
    }

import org.springframework.http.client.ClientHttpRequestFactory
import org.springframework.http.client.SimpleClientHttpRequestFactory

class Good {
    val factory: ClientHttpRequestFactory = SimpleClientHttpRequestFactory()
}
